//! Portable, wheel-only Python tool environments. uv owns dependency resolution;
//! mise owns lock persistence, interpreter selection, and executable exposure.
use super::*;
use crate::lockfile::{GraphRef, NativeGraph, UvLock};
use eyre::WrapErr;
use std::path::PathBuf;

const MIN_UV_VERSION: &str = "0.12.10";
const PROJECT_NAME: &str = "mise-pypi-tool-environment";

impl PIPXBackend {
    pub(crate) fn uv_lock_allowed(&self, tv: &ToolVersion) -> bool {
        Settings::get().pypi.uvx != Some(false)
            && !PipxOptions::new(&tv.request.options()).uvx_disabled()
            && matches!(
                self.tool_name().parse::<PipxRequest>(),
                Ok(PipxRequest::Pypi(_))
            )
    }

    fn validate_lock_options(&self, tv: &ToolVersion) -> Result<()> {
        let raw = tv.request.options();
        let opts = PipxOptions::new(&raw);
        if [opts.uvx_args(), opts.pipx_args()]
            .into_iter()
            .flatten()
            .any(|s| !s.trim().is_empty())
        {
            bail!(
                "{} dependency locking does not support uvx_args or pipx_args",
                self.ba.short
            );
        }
        if !self.uv_lock_allowed(tv) {
            bail!(
                "{} has a uv dependency graph; use uv with a PyPI package to replay it",
                self.ba.short
            );
        }
        Ok(())
    }

    async fn lock_uv_program(&self, config: &Arc<Config>) -> Result<PathBuf> {
        let uv = self.spawnable_dependency(config, None, "uv").await
            .ok_or_else(|| eyre!("Python dependency locks require uv >= {MIN_UV_VERSION}; install it with `mise use uv`"))?;
        let output = CmdLineRunner::new(&uv).arg("--version").read().await?;
        let version = output
            .split_whitespace()
            .nth(1)
            .ok_or_else(|| eyre!("cannot determine uv version"))?;
        if semver_is_older_than(version, MIN_UV_VERSION).unwrap_or(true) {
            bail!("Python dependency locks require uv >= {MIN_UV_VERSION}");
        }
        Ok(uv)
    }

    async fn configured_python_identity(&self, config: &Arc<Config>) -> Option<String> {
        let ts = self.dependency_toolset(config).await.ok()?;
        let (_, python) = ts
            .list_current_versions()
            .into_iter()
            .find(|(_, tv)| tv.ba().short == "python")?;
        Some(format!(
            "{}:{}:{}",
            python.ba().full(),
            python.version,
            python.install_path().display()
        ))
    }

    pub(crate) async fn restore_uv_python(&self, config: &Arc<Config>, tv: &mut ToolVersion) {
        if let Some(identity) = self.configured_python_identity(config).await {
            tv.uv_python = Some((PathBuf::new(), identity));
            return;
        }
        Self::restore_system_uv_python(tv);
    }

    fn restore_system_uv_python(tv: &mut ToolVersion) {
        // Installed environments remain usable without rediscovering a system Python.
        let roots = std::iter::once(tv.ba().installs_path.clone()).chain(
            crate::env::shared_install_dirs()
                .into_iter()
                .map(|root| root.join(tv.ba().tool_dir_name())),
        );
        for entry in roots
            .filter_map(|root| std::fs::read_dir(root).ok())
            .flatten()
            .flatten()
        {
            let path = entry.path();
            if !entry
                .file_name()
                .to_string_lossy()
                .starts_with(&format!("{}~uv~", tv.version))
            {
                continue;
            }
            let Ok(contents) = crate::file::read_to_string(path.join(".mise-uv/python.json"))
            else {
                continue;
            };
            let Ok(python) = serde_json::from_str::<(PathBuf, String)>(&contents) else {
                continue;
            };
            let mut candidate = tv.clone();
            candidate.uv_python = Some(python);
            if candidate.install_path() == path {
                tv.uv_python = candidate.uv_python;
                return;
            }
        }
    }

    pub(crate) async fn bind_uv_python(
        &self,
        config: &Arc<Config>,
        tv: &mut ToolVersion,
    ) -> Result<()> {
        let python = self.spawnable_dependency(config, None, "python").await
            .ok_or_else(|| eyre!("Python graph installs require an installed interpreter; run `mise install python`"))?;
        let identity = if let Some(identity) = self.configured_python_identity(config).await {
            identity
        } else {
            CmdLineRunner::new(&python).args(["-I", "-c", "import sys, sysconfig; print((sys.implementation.name, sys.version_info[:2], sysconfig.get_config_var('SOABI'), sysconfig.get_platform()))"]).read().await?.trim().to_owned()
        };
        tv.uv_python = Some((python, identity));
        Ok(())
    }

    fn lock_requirement(&self, tv: &ToolVersion) -> Result<String> {
        let PipxRequest::Pypi(package) = self.tool_name().parse()? else {
            bail!("uv graph locking requires a PyPI package");
        };
        let raw = tv.request.options();
        let opts = PipxOptions::new(&raw);
        Ok(format!(
            "{package}{}=={}",
            opts.extras().map(|v| format!("[{v}]")).unwrap_or_default(),
            tv.version
        ))
    }

    async fn uv_lock_command(
        &self,
        config: &Arc<Config>,
        tv: &ToolVersion,
        uv: &Path,
        project: &Path,
    ) -> Result<CmdLineRunner<'static>> {
        let registry = self.get_registry_url(config).await?;
        let index = uv_index_url(&registry)?;
        Ok(CmdLineRunner::new(uv)
            .current_dir(project)
            .envs(config.env().await?)
            .env_values(tv.install_env())
            .env("UV_DEFAULT_INDEX", index)
            .env_remove("UV_PROJECT")
            .env_remove("UV_WORKING_DIR")
            .env_remove("UV_PROJECT_ENVIRONMENT")
            .env_remove("VIRTUAL_ENV"))
    }

    pub(crate) async fn resolve_uv_lock(
        &self,
        config: &Arc<Config>,
        tv: &ToolVersion,
    ) -> Result<GraphRef<UvLock>> {
        self.validate_lock_options(tv)?;
        let uv = self.lock_uv_program(config).await?;
        let registry = self.get_registry_url(config).await?;
        // JSON release metadata supplies the root's Python constraint without
        // running a build backend. Simple-only indexes expose it on wheel links.
        let requires_python = if registry.ends_with("/json") {
            let url = registry.replace("{}", &format!("{}/{}", self.tool_name(), tv.version));
            let metadata: Value = HTTP_FETCH.json(&url).await?;
            metadata
                .pointer("/info/requires_python")
                .and_then(Value::as_str)
                .unwrap_or("")
                .to_owned()
        } else {
            let html = HTTP_FETCH
                .get_html(registry.replace("{}", &self.tool_name()))
                .await?;
            simple_index_python_requirement(&self.tool_name(), &tv.version, &html)
                .wrap_err_with(|| format!("failed to lock {}", self.ba.short))?
        };
        let requires_python = if requires_python.trim().is_empty() {
            ">=3.8".to_string()
        } else {
            format!(">=3.8,{requires_python}")
        };
        let requirement = self.lock_requirement(tv)?;
        let mut project = toml::Table::new();
        project.insert(
            "project".into(),
            toml::toml! {
                name = PROJECT_NAME
                version = "0.0.0"
                requires-python = requires_python
                dependencies = [requirement]
            }
            .into(),
        );
        let temp = tempfile::tempdir()?;
        crate::file::write(
            temp.path().join("pyproject.toml"),
            toml::to_string(&project)?,
        )?;
        self.uv_lock_command(config, tv, &uv, temp.path())
            .await?
            .args(["lock", "--no-build", "--no-config", "--no-python-downloads"])
            .args(Self::uv_exclude_newer_args(tv.before_date))
            .execute()?;
        let graph_text = crate::file::read_to_string(temp.path().join("uv.lock"))?;
        let graph: toml::Table = graph_text.parse()?;
        if let Some(requires_python) = graph.get("requires-python") {
            project
                .get_mut("project")
                .unwrap()
                .as_table_mut()
                .unwrap()
                .insert("requires-python".into(), requires_python.clone());
        }
        let lock = UvLock {
            project,
            graph,
            graph_text,
        };
        self.validate_uv_lock(tv, &lock)?;
        Ok(lock.into())
    }

    pub(crate) fn validate_uv_lock(&self, tv: &ToolVersion, lock: &UvLock) -> Result<()> {
        self.validate_lock_options(tv)?;
        let project = lock
            .project
            .get("project")
            .and_then(toml::Value::as_table)
            .ok_or_else(|| eyre!("missing uv project"))?;
        let expected = vec![toml::Value::String(self.lock_requirement(tv)?)];
        if project.get("dependencies").and_then(toml::Value::as_array) != Some(&expected)
            || project.get("name").and_then(toml::Value::as_str) != Some(PROJECT_NAME)
            || project.get("requires-python") != lock.graph.get("requires-python")
        {
            bail!(
                "Python lock does not match the requested tool; run `mise lock --bump {}`",
                self.ba.short
            );
        }
        let packages = lock
            .graph
            .get("package")
            .and_then(toml::Value::as_array)
            .ok_or_else(|| eyre!("missing uv packages"))?;
        let mut root = false;
        let mut virtual_root = false;
        for package in packages {
            let package = package
                format!(
                    "This package is installed with pipx because {reason}, so uv/uvx cannot be \
                     used for it.\n\nInstall pipx first:\n  mise use pipx@latest"
                )
            };
            self.warn_if_dependency_missing(&ctx.config, "pipx", &["pipx"], &instructions)
                .await;

            // Fail with the instructions above rather than letting `pipx install` die with a
            // bare "No such file or directory (os error 2)". The install graph has already
            // processed configured dependencies before this backend starts, so a configured
            // but still unspawnable pipx will not become available later in this invocation.
            //
            // The gate asks `spawnable_dependency`, the same question `spawn_program` asks
            // below, so it cannot pass on evidence the spawn will then reject. On Windows a
            // `pipx.ps1` or a shebang-only `pipx.pyz` satisfies the plain lookup but cannot
            // be launched, and it used to reach `pipx install` and die with
            // "program not found" instead of these instructions.
            if !pipx_available {
                let pipx_configured = match self.dependency_toolset(&ctx.config).await {
                    Ok(ts) => ts.versions.keys().any(|ba| ba.short == "pipx"),
                    Err(_) => false,
                };
                let reason = if pipx_configured {
                    "pipx is configured but its executable was not found or is not runnable"
                        .to_string()
                } else {
                    format!(
                        "pipx is required to install {} but was not found",
                        self.ba()
                    )
                };
                bail!(
                    "{reason}.\n\n{instructions}\n\nIf pipx is already installed, verify it with `mise which pipx` and `pipx --version`."
                );
            }
        }

        let request = self.tool_name().parse::<PipxRequest>()?;

        if let Some(uv_program) = uv_program {
            let package_request = request.uvx_request(&tv.version, &options);
            self.warn_if_uv_may_not_support_exclude_newer(ctx).await;
            ctx.pr
                .set_message(format!("uv tool install {package_request}"));
            let mut cmd = Self::uvx_cmd(
                &uv_program,
                &ctx.config,
                &["tool", "install", &package_request],
                self,
                &tv,
                &ctx.ts,
                ctx.pr.as_ref(),
            )
            .await?;
            cmd = cmd.args(Self::uv_exclude_newer_args(ctx.before_date));
            if let Some(args) = options.uvx_args() {
                cmd = cmd.args(shell_words::split(args)?);
            }
            cmd.execute()?;
        } else {
            // pipx forwards install `--pip-args` into shared-library bootstrap
            // (`pip install --upgrade pip>=23.1`), not just the package install. When mise
            // passes `--uploaded-prior-to`, bootstrap pip from ensurepip may not understand
            // that flag (see pypa/pipx#544). Run upgrade-shared without release-age flags
            // first so shared pip is valid; the subsequent install's shared_libs.create()
            // then no-ops and `--uploaded-prior-to` applies only to the package install.
            if ctx.before_date.is_some() {
                ctx.pr.set_message("pipx upgrade-shared".to_string());
                if let Err(err) = async {
                    Self::pipx_cmd(
                        &ctx.config,
                        &["upgrade-shared"],
                        self,
                        &tv,
                        &ctx.ts,
                        ctx.pr.as_ref(),
                    )
                    .await?
                    .execute()
                }
                .await
                {
                    debug!("failed to upgrade pipx shared libraries before install: {err:#}");
                }
            }

            let package_request = request.pipx_request(&tv.version, &options);
            ctx.pr
                .set_message(format!("pipx install {package_request}"));
            let mut cmd = Self::pipx_cmd(
                &ctx.config,
                &["install", &package_request],
                self,
                &tv,
                &ctx.ts,
                ctx.pr.as_ref(),
            )
            .await?;
            cmd = cmd.args(Self::pip_uploaded_prior_to_args(ctx.before_date));
            if let Some(args) = options.pipx_args() {
                cmd = cmd.args(shell_words::split(args)?);
            }
            if let Err(err) = cmd.execute() {
                let not_found = err.chain().any(|cause| {
                    cause
                        .downcast_ref::<std::io::Error>()
                        .is_some_and(|io| io.kind() == std::io::ErrorKind::NotFound)
                });
                if not_found {
                    bail!(
                        "pipx was found during dependency validation but could not be launched while installing {}.\n\nVerify the configured executable with `mise which pipx` and `pipx --version`. If pipx is unavailable, reinstall it with `mise use pipx@latest`.",
                        self.ba()
                    );
                }
                return Err(err);
            }
        }

        // Fix venv Python symlink to use minor version path
        // This allows patch upgrades (3.12.1 → 3.12.2) to work without reinstalling
        let pkg_name = self.tool_name();
        fix_venv_python_symlink(&tv.install_path(), &pkg_name)?;

        Ok(tv)
    }

    fn resolve_lockfile_options(
        &self,
        request: &ToolRequest,
        _target: &PlatformTarget,
    ) -> Result<BTreeMap<String, String>> {
        let opts = request.options();
        Ok(PipxOptions::new(&opts).lockfile_options())
    }
}

/// Returns install-time-only option keys for PIPX backend.
pub(crate) fn install_time_option_keys() -> Vec<String> {
    vec![
        "extras".into(),
        "package_name".into(),
        "pipx_args".into(),
        "uvx_args".into(),
        "uvx".into(),
    ]
}

impl PIPXBackend {
    /// Resolves a Git remote's default-branch HEAD to a concrete commit SHA.
    async fn git_head(url: &str) -> Result<String> {
        let remote = format!("{url}.git");
        timeout::run_with_timeout_async(
            async || {
                let output = crate::cmd::cmd_read_async_inherited_env(
                    "git",
                    &["ls-remote", &remote, "HEAD"],
                    std::iter::empty::<(&str, &std::ffi::OsStr)>(),
                )
                .await?;
                Self::git_head_from_ls_remote(&output)
                    .ok_or_else(|| eyre!("no HEAD found for {remote}"))
            },
            Settings::get().fetch_remote_versions_timeout(),
        )
        .await
    }

    /// Parses the concrete HEAD commit from `git ls-remote <url> HEAD` output.
    fn git_head_from_ls_remote(output: &str) -> Option<String> {
        output.lines().find_map(|line| {
            let (sha, git_ref) = line.split_once('\t')?;
            (git_ref == "HEAD").then(|| sha.to_string())
        })
    }

    /// Lists tags from a Git remote while preserving Git's source ordering.
    async fn versions_from_git_tags(url: &str) -> Result<Vec<VersionInfo>> {
        let remote = format!("{url}.git");
        timeout::run_with_timeout_async(
            async || {
                let output = crate::cmd::cmd_read_async_inherited_env(
                    "git",
                    &["ls-remote", "--tags", "--refs", &remote],
                    std::iter::empty::<(&str, &std::ffi::OsStr)>(),
                )
                .await?;
                Ok(Self::versions_from_git_ls_remote(&output))
            },
            Settings::get().fetch_remote_versions_timeout(),
        )
#!/usr/bin/env bash
set -euo pipefail

mise install uv@0.12.10 python@3.12.11
python3 "$ROOT/e2e/fixtures/pypi/server.py" "$PWD/index" &
server_pid=$!
trap 'kill "$server_pid"' EXIT
for _ in {1..100}; do
  [[ -s index/port ]] && break
  sleep 0.1
done
port=$(cat index/port)
cat >mise.toml <<EOF_CONFIG
[tools]
uv = "0.12.10"
python = "3.12.11"
"pipx:mise-lock-cli" = "1.0.0"
[settings]
minimum_release_age = "0"
pypi.registry_url = "http://127.0.0.1:$port/pypi/{}/json"
EOF_CONFIG
mise trust
cp mise.toml original.toml
mise lock
assert_contains "cat mise.lock" 'lockfile_version = 2'
assert_contains "cat mise.lock" 'tools."pipx:mise-lock-cli"'
assert_contains "cat mise.lock" 'path = ".mise/locks/pipx-mise-lock-cli/1.0.0"'
assert_contains "cat .mise/locks/pipx-mise-lock-cli/1.0.0/uv.lock" 'mise-lock-marker'
assert_contains "mise x --locked -- lock-cli" 'dependency=1.0.0'
first_path=$(mise where pipx:mise-lock-cli)
assert "mise where pipx:mise-lock-cli" "$first_path"
assert_contains_text "$first_path" 'pipx-mise-lock-cli/1.0.0~uv~'
# The universal graph contains the older-Python branch but does not install it on 3.12.
assert_fail "'$first_path/.mise-uv/.venv/bin/python' -I -c \"import importlib.metadata; importlib.metadata.version('mise-lock-marker')\""
assert_fail 'MISE_DISABLE_BACKENDS=pipx mise install pypi:disabled-test@1.0.0' 'disabled by disable_backends'
assert_fail 'MISE_DISABLE_BACKENDS=pypi mise install pipx:disabled-test@1.0.0' 'disabled by disable_backends'
cp mise.lock first.lock
cp -R .mise/locks first-sidecars
# Newly published dependencies do not affect replay or ordinary locking.
touch index/publish
mise lock
assert_succeed 'cmp first.lock mise.lock'
assert_contains "mise x --locked -- lock-cli" 'dependency=1.0.0'
mise lock --bump pipx:mise-lock-cli
assert_contains "mise x --locked -- lock-cli" 'dependency=2.0.0'
second_path=$(mise where pipx:mise-lock-cli)
assert_succeed "test '$first_path' != '$second_path'"
# External edits are rejected by locked installs, accepted by ordinary installs.
cp mise.lock before-edit.lock
printf '\n# external edit\n' >>.mise/locks/pipx-mise-lock-cli/1.0.0/uv.lock
assert_fail 'mise install --locked pipx:mise-lock-cli' 'accept the edited graph'
assert_contains "mise x -- lock-cli" 'dependency=2.0.0'
mise install pipx:mise-lock-cli
assert "mise where pipx:mise-lock-cli" "$second_path"
assert_succeed 'cmp before-edit.lock mise.lock'
mise lock
mise install pipx:mise-lock-cli
edited_path=$(mise where pipx:mise-lock-cli)
assert_succeed "test '$edited_path' != '$second_path'"
assert_fail 'cmp before-edit.lock mise.lock'
assert_contains "mise x --locked -- lock-cli" 'dependency=2.0.0'
# Generate-mode hot installs use only the recorded graph identity without uv.
cp mise.toml hot-config.toml
python3 - <<'PY_HOT'
from pathlib import Path
p = Path('mise.toml')
p.write_text(p.read_text().replace('uv = "0.12.10"\n', ''))
PY_HOT
MISE_LOCKFILE_MODE=generate mise lock
mise uninstall uv
cp mise.lock hot.lock
cp .mise/locks/pipx-mise-lock-cli/1.0.0/uv.lock hot-uv.lock
printf 'unreadable graph contents' >.mise/locks/pipx-mise-lock-cli/1.0.0/uv.lock
MISE_LOCKFILE_MODE=generate mise install
assert_succeed 'cmp hot.lock mise.lock'
cp hot-uv.lock .mise/locks/pipx-mise-lock-cli/1.0.0/uv.lock
cp hot-config.toml mise.toml
mise install uv
# Extras participate in resolution and installation identity.
python3 - <<'PY_EXTRAS'
from pathlib import Path
p = Path('mise.toml')
p.write_text(p.read_text().replace('"pipx:mise-lock-cli" = "1.0.0"', '"pipx:mise-lock-cli" = { version = "1.0.0", extras = "feature" }'))
PY_EXTRAS
mise lock --bump pipx:mise-lock-cli
assert_contains "mise x --locked -- lock-cli" 'extra=1.0.0'
assert_succeed "find .mise/locks/pipx-mise-lock-cli -maxdepth 1 -name '1.0.0~*' | grep -q ."
cp original.toml mise.toml
mise lock
assert_fail "find .mise/locks/pipx-mise-lock-cli -maxdepth 1 -name '1.0.0~*' | grep -q ."
# Return to the first graph and reinstall with an empty artifact cache.
cp first.lock mise.lock
cp first-sidecars/pipx-mise-lock-cli/1.0.0/* .mise/locks/pipx-mise-lock-cli/1.0.0/
python3 - <<'PY_INCOMPATIBLE'
import re
from pathlib import Path
for name in ['uv.lock', 'pyproject.toml']:
    p = Path('.mise/locks/pipx-mise-lock-cli/1.0.0') / name
    p.write_text(re.sub(r'(?m)^requires-python = .*$', 'requires-python = ">=3.99"', p.read_text()))
PY_INCOMPATIBLE
mise lock
assert_fail 'mise install --locked pipx:mise-lock-cli'
cp first.lock mise.lock
cp first-sidecars/pipx-mise-lock-cli/1.0.0/* .mise/locks/pipx-mise-lock-cli/1.0.0/
python3 - <<'PY_OPTIONS'
from pathlib import Path
p = Path('mise.toml')
p.write_text(p.read_text().replace('"pipx:mise-lock-cli" = "1.0.0"', '"pipx:mise-lock-cli" = { version = "1.0.0", uvx_args = "--prerelease allow" }'))
PY_OPTIONS
assert_fail 'mise lock --bump pipx:mise-lock-cli' 'dependency locking does not support'
cp original.toml mise.toml
mise uninstall --all pipx:mise-lock-cli
export UV_CACHE_DIR="$PWD/corrupt-cache"
touch index/corrupt
if corrupt_output=$(mise install --locked pipx:mise-lock-cli 2>&1); then
  fail 'corrupted wheels must fail installation'
fi
echo "$corrupt_output"
assert_contains_text "$corrupt_output" 'Hash mismatch'
assert_fail 'MISE_PYPI_UVX=false mise install --locked pipx:mise-lock-cli'
# Settings aliases must never silently contradict one another.
assert_fail 'MISE_PIPX_UVX=false MISE_PYPI_UVX=true mise settings'
# Both settings spellings read the same value; writes use the preferred name.
assert 'mise settings get pipx.registry_url' "http://127.0.0.1:$port/pypi/{}/json"
mise settings set --local pipx.uvx false
assert 'mise settings get pypi.uvx' 'false'
assert 'mise settings get --local pipx.uvx' 'false'
mise settings unset --local pipx.uvx
assert_fail 'mise settings get --local pypi.uvx'
# Conflicting file aliases still permit targeted repair, including --cd.
mkdir repair
cat >repair/mise.toml <<'REPAIR_CONFIG'
[settings]
pypi.uvx = true
pipx.uvx = false
REPAIR_CONFIG
assert_fail 'mise --cd repair settings get pypi.uvx'
mise --cd repair settings set --local pipx.uvx true
assert 'mise --cd repair settings get pypi.uvx' 'true'
cat >repair/mise.toml <<'REPAIR_CONFIG'
[settings]
pypi.uvx = true
pipx.uvx = false
REPAIR_CONFIG
mise --cd repair settings unset --local pipx.uvx
assert_fail 'mise --cd repair settings get --local pypi.uvx'

# Environment aliases override either spelling in a file; only same-source conflicts fail.
cat >repair/mise.toml <<'EOF_PRECEDENCE'
[settings]
pypi.uvx = true
EOF_PRECEDENCE
assert 'MISE_PIPX_UVX=false mise --cd repair settings get pypi.uvx' 'false'
cat >repair/mise.toml <<'EOF_PRECEDENCE'
[settings]
pipx.uvx = true
EOF_PRECEDENCE
assert 'MISE_PYPI_UVX=false mise --cd repair settings get pipx.uvx' 'false'
assert 'MISE_PIPX_UVX=false mise settings get pypi.uvx' 'false'
assert 'MISE_PYPI_UVX=false mise settings get pipx.uvx' 'false'

# Backend spellings share settings but create distinct installs and lock entries.
rm index/corrupt
cp original.toml mise.toml
python3 - <<'PY_SPELLING'
from pathlib import Path
p = Path('mise.toml')
p.write_text(p.read_text().replace('pipx:mise-lock-cli', 'pypi:mise-lock-cli'))
PY_SPELLING
mise lock
mise install pypi:mise-lock-cli
preferred_path=$(mise where pypi:mise-lock-cli)
assert_contains_text "$preferred_path" 'pypi-mise-lock-cli/'
assert_succeed "test '$preferred_path' != '$first_path'"
assert_contains "cat mise.lock" 'tools."pypi:mise-lock-cli"'
assert_not_contains "cat mise.lock" 'tools."pipx:mise-lock-cli"'
assert_contains "cat mise.lock" '.mise/locks/pypi-mise-lock-cli/'

# A version-only revision-2 entry cannot silently fall back under --locked.
cp original.toml mise.toml
python3 - <<'PY_NO_UV'
from pathlib import Path
p = Path('mise.toml')
p.write_text(p.read_text().replace('uv = "0.12.10"\n', ''))
PY_NO_UV
mise uninstall uv
# A dangling pointer survives saves when uv is unavailable to repair it.
cp first.lock mise.lock
mkdir -p .mise/locks/pipx-mise-lock-cli/1.0.0
printf 'invalid lock text' >.mise/locks/pipx-mise-lock-cli/1.0.0/uv.lock
mise lock
assert_contains "cat mise.lock" 'uv ='
cat >mise.lock <<'EOF_NO_GRAPH'
lockfile_version = 2
[[tools."pipx:mise-lock-cli"]]
version = "1.0.0"
backend = "pipx:mise-lock-cli"
specifiers = ["1.0.0"]
EOF_NO_GRAPH
assert_fail 'mise install --locked pipx:mise-lock-cli' 'has no uv dependency graph'

