        &mut candidate,
        tools,
        Some(report.as_ref()),
        false,
    ))
    .await?;
    candidate.cleanup_unreferenced_conda_packages();
    candidate.cleanup_unreferenced_pkgx_packages();
    report.finish_with_message(format!("{completed} targets checked"));
    progress.finished = true;
    Ok(candidate)
}

