691	    config: &Arc<Config>,
692	    lockfile: &mut Lockfile,
693	    tools: &[Tool],
694	    force: bool,
695	) -> Result<()> {
696	    if lockfile.lockfile_version() < 2 {
697	        return Ok(());
698	    }
699	    for (ba, tv) in tools {
700	        if ba.backend_type() != BackendType::Pipx {
701	            continue;
702	        }
703	        let backend = crate::backend::pipx::PIPXBackend::from_arg(ba.clone());
704	        let options =
705	            backend.resolve_lockfile_options(&tv.request, &PlatformTarget::from_current())?;
706	        let backend_name = ba.stored_full();
707	        if !backend.uv_lock_allowed(tv) {
708	            if let Some(entries) = lockfile.tools_for_mut(&ba.short) {
709	                for entry in entries
710	                    .iter_mut()
711	                    .filter(|entry| entry.version == tv.version && entry.options == options)
712	                {
713	                    entry.uv = None;
714	                }
715	            }
716	            continue;
717	        }
718	        if let Some(lock) = lockfile
719	            .tools_for(&ba.short)
720	            .and_then(|entries| {
721	                entries.iter().find(|entry| {
722	                    entry.version == tv.version
723	                        && entry.backend.as_deref().is_none_or(|b| b == backend_name)
724	                        && entry.options == options
725	                })
726	            })
727	            .and_then(|entry| entry.uv.as_ref())
728	            && !force
729	        {
730	            let candidate = if lock.load().is_ok() {
731	                Some(lock.clone())
732	            } else {
733	                lock.refresh().ok()
734	            };
735	            if let Some(candidate) = candidate {
736	                backend.validate_uv_lock(tv, candidate.load()?)?;
737	                lockfile.set_uv_lock(&ba.short, &tv.version, &backend_name, &options, candidate)?;
738	                continue;
739	            }
740	        }
741	        if backend
742	            .spawnable_dependency(config, None, "uv")
743	            .await
744	            .is_none()
745	        {
746	            warn!(
747	                "{} dependency graph skipped: uv >= 0.12.10 is unavailable; install uv and run `mise lock` again",
748	                ba.short
749	            );
